#include <memory>
#include <iostream>

class Data {};

int main() {
    // Correct: Allocated with single object new
    std::auto_ptr<Data> p1(new Data);

    // DANGER: Allocated with array new
    // This will lead to undefined behavior/memory corruption upon destruction.
    // std::auto_ptr<Data> p2(new Data[10]); 

    // The use of 'delete' in the destructor is implicit:
    // ~auto_ptr() { delete get(); }

    // To manage an array safely (if forced to use auto_ptr):
    // You must manually release and delete[]
    Data* arr = new Data[5];
    std::auto_ptr<Data> p3(arr); // Still dangerous, only manages 'arr[0]'
    p3.release(); // Relinquish ownership
    delete[] arr; // Manual cleanup required
}
